output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper is obliged to take the entry cart before proceeding with the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "A shopper is prohibited from picking up merchandise unless they are currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying items loose by hand rather than transporting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_transport_mode": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "item_becomes_hand_carried": {
          "pre": "PICKUP_ITEM",
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "item_becomes_hand_carried"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_northwest_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the northwest cart-return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "northwest_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "northwest_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_entry_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment_elsewhere",
    "text": "A shopper is prohibited from leaving the cart anywhere except the northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "authorized_cart_return_bay": "at(0,1)",
        "unauthorized_cart_location": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "unauthorized_cart_location"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_encumbered",
    "text": "A shopper is prohibited from exiting while still pushing a cart or carrying goods by hand.",
    "abstraction": {
      "state_properties": {
        "encumbered": {
          "or": [
            "hasCart",
            "handFull"
          ]
        }
      },
      "events": {
        "exit_while_encumbered": {
          "pre": {
            "and": [
              "encumbered",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_encumbered"
    }
  },
  {
    "id": "drop_cart_immediately_at_return_bay",
    "text": "When a shopper reaches the northwest return bay while pushing a cart, they must leave the cart there immediately rather than moving on with it.",
    "abstraction": {
      "state_properties": {
        "at_return_bay_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        }
      },
      "events": {
        "proper_immediate_cart_drop": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "fail_to_drop_at_return_bay": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              {
                "not": "LEAVE_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "fail_to_drop_at_return_bay"
    }
  },
  {
    "id": "no_carts_in_exit_pedestrian_zone",
    "text": "Shopping carts are prohibited in the exit-side pedestrian zone, so shoppers must enter that zone on foot after returning the cart.",
    "abstraction": {
      "state_properties": {
        "exit_pedestrian_zone": {
          "or": [
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "pushing_cart_in_exit_zone": {
          "and": [
            "hasCart",
            "exit_pedestrian_zone"
          ]
        }
      },
      "events": {
        "enter_exit_zone_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "exit_pedestrian_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "pushing_cart_in_exit_zone",
          "enter_exit_zone_with_cart"
        ]
      }
    }
  }
]
